import { MeshBasicNodeMaterial, PlaneGeometry, Group } from 'three/webgpu';

export default function createNode(config, ctx) {
  // Load texture (synchronous, cached)
  const texture = ctx.textureLoader.load(config.assets.imageUrl);

  // Atlas region source rect: 0,0,512,320
  // Assume texture is exactly this region – no UV offset needed
  // Aspect ratio for geometry
  const aspect = 512 / 320;

  const geometry = new PlaneGeometry(aspect, 1);

  const material = new MeshBasicNodeMaterial({
    map: texture,
  });

  const mesh = new Group(); // Use group as container for plane
  const plane = new THREE.Mesh(geometry, material);
  // Rotate to face camera (default orientation already faces -Z)
  // Camera is at (0,0,10) looking at origin – this works.
  mesh.add(plane);

  // Placement
  mesh.position.set(config.position.x, config.position.y, config.position.z);
  mesh.rotation.set(config.rotation.x, config.rotation.y, config.rotation.z);
  mesh.scale.set(config.scale.x, config.scale.y, config.scale.z);

  // No interactions
  mesh.userData.handlers = {};

  // Cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return mesh;
}
